mapper.select:
SELECT r.reta_batch_id AS retaBatchId, r.batch_no AS batchNo, r.trace_code AS traceCode, r.product_code AS productCode, r.breed AS breed, r.product_type AS productType, r.product_form AS productForm, r.spec_grade AS specGrade, r.price AS price, r.image_url AS imageUrl, r.quality_status AS qualityStatus, rn.name AS retailerName, rn.address AS retailerAddress, f.breed AS farmBreed, f.source_type AS sourceType, fn.name AS farmName, p.prov_name AS originProvince, p.prov_id AS originProvId FROM reta_batch r LEFT JOIN node_info rn ON rn.node_id = r.node_id LEFT JOIN whol_batch w ON w.batch_no = r.up_batch_no LEFT JOIN froz_batch z ON z.batch_no = w.up_batch_no LEFT JOIN farm_batch f ON f.batch_no = z.up_batch_no LEFT JOIN node_info fn ON fn.node_id = f.node_id LEFT JOIN province p ON p.prov_id = fn.prov_id WHERE r.status = 3 AND r.trace_code IS NOT NULL AND (r.quality_status IS NULL OR r.quality_status <> 2)
AND (r.breed LIKE CONCAT('%', #{keyword}, '%') OR r.product_type LIKE CONCAT('%', #{keyword}, '%') OR r.batch_no LIKE CONCAT('%', #{keyword}, '%') OR r.product_code LIKE CONCAT('%', #{keyword}, '%'))
AND r.product_form = #{form}
AND fn.prov_id = #{provId}
ORDER BY r.reta_batch_id DESC
